<script setup lang="ts">
import type { BsAdminCommerceCopy, BsAdminCommerceView, BsAdminSupportForm, BsAdminReceiptReviewForm, BsAdminPriceForm, BsAdminPaymentConfigurationForm } from '../types/platformAdministrationPresentation'
defineProps<{ copy: BsAdminCommerceCopy; view: BsAdminCommerceView }>()
const support = defineModel<BsAdminSupportForm>('support', { required: true })
const receipt = defineModel<BsAdminReceiptReviewForm>('receipt', { required: true })
const price = defineModel<BsAdminPriceForm>('price', { required: true })
const configuration = defineModel<BsAdminPaymentConfigurationForm>('configuration', { required: true })
const emit = defineEmits<{ close: [kind: 'support' | 'receipt' | 'price' | 'configuration']; support: []; receipt: []; price: []; configuration: [] }>()
function setSupport<K extends keyof BsAdminSupportForm>(key: K, value: BsAdminSupportForm[K]) { support.value = { ...support.value, [key]: value } }
function setReceipt<K extends keyof BsAdminReceiptReviewForm>(key: K, value: BsAdminReceiptReviewForm[K]) { receipt.value = { ...receipt.value, [key]: value } }
function setPrice<K extends keyof BsAdminPriceForm>(key: K, value: BsAdminPriceForm[K]) { price.value = { ...price.value, [key]: value } }
function setConfiguration(key: keyof BsAdminPaymentConfigurationForm, value: unknown) { configuration.value = { ...configuration.value, [key]: String(value ?? '') } }
</script>
<template>
  <BsRecordActionDialog :visible="view.supportDialog.visible" :title="view.supportDialog.title" :dirty="view.supportDialog.dirty" :pending="view.supportDialog.pending" :error="view.supportDialog.error" :submit-label="copy.save" :cancel-label="copy.cancel" @update:visible="value => { if (!value) emit('close', 'support') }" @submit="emit('support')">
    <BsFloatingField :label="copy.reason"><BsTextarea :model-value="support.reason" :minlength="2" :maxlength="1000" required :rows="3" @update:model-value="setSupport('reason', String($event ?? ''))"/></BsFloatingField>
    <BsFloatingField v-if="view.supportDialog.showDays" :label="copy.days"><BsInput :model-value="support.days" type="number" :min="1" :max="365" :step="1" required @update:model-value="setSupport('days', Number($event))"/></BsFloatingField>
    <template v-if="view.supportDialog.showBilling"><BsFloatingField :label="copy.billingReference"><BsInput :model-value="support.reference" :maxlength="200" @update:model-value="setSupport('reference', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.billingNote"><BsTextarea :model-value="support.billingNote" :maxlength="1000" :rows="3" @update:model-value="setSupport('billingNote', String($event ?? ''))"/></BsFloatingField></template>
    <BsFloatingField v-if="view.supportDialog.showNote" :label="copy.note"><BsTextarea :model-value="support.note" :minlength="2" :maxlength="2000" required :rows="5" @update:model-value="setSupport('note', String($event ?? ''))"/></BsFloatingField>
  </BsRecordActionDialog>
  <BsRecordActionDialog :visible="view.receiptDialog.visible" :title="view.receiptDialog.title" :dirty="view.receiptDialog.dirty" :pending="view.receiptDialog.pending" :error="view.receiptDialog.error" :submit-label="copy.save" :cancel-label="copy.cancel" @update:visible="value => { if (!value) emit('close', 'receipt') }" @submit="emit('receipt')">
    <BsFloatingField :label="copy.reason"><BsTextarea :model-value="receipt.reason" :minlength="2" :maxlength="1000" required :rows="3" @update:model-value="setReceipt('reason', String($event ?? ''))"/></BsFloatingField>
    <template v-if="view.receiptDialog.approving"><BsFloatingField :label="copy.receivedAmount"><BsInput :model-value="receipt.amount" type="number" :min="0.01" :step="0.01" required @update:model-value="setReceipt('amount', Number($event))"/></BsFloatingField><BsFloatingField :label="copy.receivedReference"><BsInput :model-value="receipt.reference" dir="ltr" :minlength="2" :maxlength="200" required @update:model-value="setReceipt('reference', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.receivedDate"><BsInput :model-value="receipt.date" type="date" :max="view.receiptDialog.maxDate" required @update:model-value="setReceipt('date', String($event ?? ''))"/></BsFloatingField><BsFloatingField v-if="view.receiptDialog.mismatched" :label="copy.mismatchReason"><BsTextarea :model-value="receipt.mismatchReason" :minlength="2" :maxlength="1000" required :rows="3" @update:model-value="setReceipt('mismatchReason', String($event ?? ''))"/></BsFloatingField></template>
  </BsRecordActionDialog>
  <BsRecordActionDialog :visible="view.priceDialog.visible" :title="view.priceDialog.title" :dirty="view.priceDialog.dirty" :pending="view.priceDialog.pending" :error="view.priceDialog.error" :submit-label="copy.save" :cancel-label="copy.cancel" @update:visible="value => { if (!value) emit('close', 'price') }" @submit="emit('price')">
    <BsFloatingField :label="copy.overrideAmount"><BsInput :model-value="price.amount" type="number" :min="0.01" :step="0.01" required @update:model-value="setPrice('amount', Number($event))"/></BsFloatingField><BsFloatingField :label="copy.effectiveFrom"><BsInput :model-value="price.effectiveFrom" type="date" required @update:model-value="setPrice('effectiveFrom', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.expiresAt"><BsInput :model-value="price.expiresAt" type="date" :min="price.effectiveFrom" @update:model-value="setPrice('expiresAt', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.reason"><BsTextarea :model-value="price.reason" :minlength="2" :maxlength="1000" required :rows="3" @update:model-value="setPrice('reason', String($event ?? ''))"/></BsFloatingField>
  </BsRecordActionDialog>
  <BsRecordActionDialog :visible="view.configuration.visible" :title="copy.configuration" :dirty="view.configuration.dirty" :pending="view.configuration.pending" :error="view.configuration.error" :submit-label="copy.save" :cancel-label="copy.cancel" :submit-disabled="!view.canMutate" @update:visible="value => { if (!value) emit('close', 'configuration') }" @submit="emit('configuration')">
    <BsFieldGroup :disabled="!view.canMutate || view.configuration.pending" :legend="''"><BsFloatingField :label="copy.recipient"><BsInput :model-value="configuration.recipient" dir="ltr" :maxlength="200" @update:model-value="setConfiguration('recipient', $event)"/></BsFloatingField><BsFloatingField :label="copy.paymentLink"><BsInput :model-value="configuration.paymentLink" dir="ltr" :maxlength="1000" @update:model-value="setConfiguration('paymentLink', $event)"/></BsFloatingField><BsFloatingField :label="copy.qrImageUrl"><BsInput :model-value="configuration.qrImageUrl" dir="ltr" :maxlength="1000" @update:model-value="setConfiguration('qrImageUrl', $event)"/></BsFloatingField><BsFloatingField :label="copy.instructionsEn"><BsTextarea :model-value="configuration.instructionsEn" dir="ltr" :maxlength="2000" :rows="4" @update:model-value="setConfiguration('instructionsEn', $event)"/></BsFloatingField><BsFloatingField :label="copy.instructionsAr"><BsTextarea :model-value="configuration.instructionsAr" dir="rtl" :maxlength="2000" :rows="4" @update:model-value="setConfiguration('instructionsAr', $event)"/></BsFloatingField><BsFloatingField :label="copy.reason"><BsTextarea :model-value="configuration.reason" :minlength="2" :maxlength="1000" required :rows="2" @update:model-value="setConfiguration('reason', $event)"/></BsFloatingField></BsFieldGroup>
  </BsRecordActionDialog>
</template>
